export class LocalStorage {
    private static _isAvailable: boolean;

    private static inMemoryStorage: Map<string, string | number | boolean | object> = new Map();

    private static runTest() {
        try {
            window.localStorage.setItem('test', 'tombola');
            return true;
        } catch (error) {
            return false;
        }
    }

    public static get isAvailable() {
        if (this._isAvailable === void 0) {
            this._isAvailable = this.runTest();
        }

        return this._isAvailable;
    }

    public static setItem(key: string, value: string | number | boolean | object) {
        if (this.isAvailable) {
            window.localStorage.setItem(key, JSON.stringify(value));
        } else {
            this.inMemoryStorage.set(key, value);
        }
    }

    public static getItem<T extends string | number | boolean | object>(key: string) {
        if (this.isAvailable) {
            const value = window.localStorage.getItem(key);

            try {
                return value === null ? null : JSON.parse(value) as T;
            } catch {
                return value === null ? null : value as T;
            }
        } else {
            return this.inMemoryStorage.get(key) as T;
        }
    }

    public static removeItem(key: string) {
        if (this.isAvailable) {
            window.localStorage.removeItem(key);
        } else {
            this.inMemoryStorage.delete(key);
        }
    }

    public static clear() {
        if (this.isAvailable) {
            window.localStorage.clear();
        } else {
            this.inMemoryStorage.clear();
        }
    }
}
